23	// DEVDESK-579 (NX-12), step 5: a Nexus group member is searched through its own
24	// catalog, /v2/<repo_prefix>/_catalog, never through the root /v2/_catalog that
25	// Nexus does not serve on the HTTP port (measured, 404 page). The browser sets
26	// CatalogUnderPrefix on every entry whose group is declared `provider: nexus`:
27	// the members discovered for it and the entries that declare it as `parent:`.
28	// Entries of any other registry keep the root catalog and R1 (D140).
29	//
30	// The answers come from the fixtures measured on the bench (Nexus 3.98.1-01),
31	// replayed by fakenexus; the failures nobody measured (5xx, 429) use httptest.
32	
33	// benchHTTPPort is the recorded Host of the bench's REST port, where hosted and
34	// proxy repositories answer under /v2/<repository>/ (docker.pathEnabled).
35	const benchHTTPPort = "127.0.0.1:30481"
36	
37	// nexusFake replays the measured catalog campaign and returns it with the
38	// fixtures, so a test can name which recording answered.
39	func nexusFake(t *testing.T) (*fakenexus.Server, []nexusfixture.Fixture) {
40		t.Helper()
41		fixtures, err := nexusfixture.Load("catalog")
42		if err != nil || len(fixtures) == 0 {
43			t.Fatalf("Load(catalog) = %d fixtures, %v", len(fixtures), err)
44		}
45		return fakenexus.New(t, fixtures...), fixtures
46	}
47	
48	// nexusOnlySearcher is the production routing with a Docker Hub that must never
49	// be asked: a Nexus member is not Docker Hub.
50	func nexusOnlySearcher(t *testing.T) imagesearch.Searcher {
51		t.Helper()
52		hub := httptest.NewServer(http.HandlerFunc(func(_ http.ResponseWriter, r *http.Request) {
53			t.Errorf("Docker Hub was asked: %s", r.URL.Path)
54		}))
55		t.Cleanup(hub.Close)
56		return wiredLikeProduction(hub)
57	}
