59	// modelWithGroups opens the browser on items with the discovered members of the
60	// groups, as the Registries tab's cache would give them.
61	func modelWithGroups(t *testing.T, items []config.RegistryItem, groups map[string]cache.RegistryGroupEntry) Model {
62		t.Helper()
63		cfg := testConfig()
64		cfg.Registry.Registries = items
65		m := feed(t, New(cfg), testutil.Resize(200, 40),
66			ImagesListMsg{Images: imageFixtures()},
67			RegistryGroupCacheLoadedMsg{Entries: groups},
68		)
69		m = feed(t, m, testutil.Key(keymap.Browser))
70		if m.registryBrowser == nil {
71			t.Fatal("'b' did not open the registry browser")
72		}
73		return m
74	}
