76	// anonymousNexusGroup is the Nexus group "nx" at base, read without credentials.
77	func anonymousNexusGroup(base string) config.RegistryItem {
78		g := nexusGroup()
79		g.AuthMode = config.AuthAnonymous
80		g.URL = base
81		return g
82	}
83	
84	// discoveredMembers are members of "nx" the way discovery stores them for a
85	// path-routed group: the host of the HTTP port plus one prefix each.
86	func discoveredMembers(base string, prefixes ...string) map[string]cache.RegistryGroupEntry {
87		var members []cache.RegistryGroupMember
88		for _, p := range prefixes {
89			members = append(members, cache.RegistryGroupMember{Alias: p, URL: base, RepoPrefix: p})
90		}
91		return map[string]cache.RegistryGroupEntry{"nx": {Members: members}}
92	}
