94	// nexusMembersModel opens the browser on the anonymous group "nx" whose
95	// discovered members are the given prefixes at base.
96	func nexusMembersModel(t *testing.T, base string, prefixes ...string) Model {
97		t.Helper()
98		return modelWithGroups(t, []config.RegistryItem{anonymousNexusGroup(base)}, discoveredMembers(base, prefixes...))
99	}
