101	// declaredMember is an entry declared by hand under the group "nx".
102	func declaredMember(base, slug, prefix string) config.RegistryItem {
103		return config.RegistryItem{
104			URL: base, Alias: slug, Slug: slug, Kind: config.KindRegistry,
105			Parent: "nx", RepoPrefix: prefix, AuthMode: config.AuthAnonymous,
106		}
107	}
