109	// wantOnlyMemberCatalogsAsked checks that a Nexus-by-path lot asked the two member
110	// catalogs once each and nothing else: no root catalog, no connector, no other recording.
111	func wantOnlyMemberCatalogsAsked(t *testing.T, s *fakenexus.Server, fixtures []nexusfixture.Fixture) {
112		t.Helper()
113		for _, name := range []string{"catalog-hosted-path--anon", "catalog-proxy-path--anon"} {
114			if h := s.Hits(name); h != 1 {
115				t.Errorf("Hits(%s) = %d, want 1 (one walk per member)", name, h)
116			}
117		}
118		for _, f := range fixtures {
119			if strings.Contains(f.Name, "-root-") || strings.Contains(f.Name, "-connector-") {
120				if h := s.Hits(f.Name); h != 0 {
121					t.Errorf("Hits(%s) = %d, want 0: the root /v2/_catalog was asked", f.Name, h)
122				}
123			}
124		}
125		total := 0
126		for _, f := range fixtures {
127			total += s.Hits(f.Name)
128		}
129		if total != 2 {
130			t.Errorf("%d requests answered in total, want 2", total)
131		}
132	}
