140	// Criteria 1, 2, 4 and 5: two members of one host, addressed by path, are one
141	// walk each on their own catalog; their rows carry their own reference, the
142	// verdicts are per member, and the root catalog is never asked.
143	func TestNexusMembersByPathWalkTheirOwnCatalog(t *testing.T) {
144		tests := []struct {
145			name  string
146			query string
147			// rows by member prefix; a member with no row answered "no result".
148			hosted, proxy []string
149		}{
150			{
151				// shared/base is in BOTH catalogs: each member lists it, with its own
152				// reference (a pull through the group would resolve it to the first).
153				name: "a name both members hold", query: "base",
154				hosted: []string{"docker-hosted/shared/base"},
155				proxy:  []string{"docker-proxy/shared/base"},
156			},
157			{
158				name: "a name only the hosted member holds", query: "api",
159				hosted: []string{"docker-hosted/api", "docker-hosted/team/api"},
160			},
161			{
162				name: "a name only the proxy member holds", query: "mirror",
163				proxy: []string{"docker-proxy/mirror/cached", "docker-proxy/mirror/uncached"},
164			},
165		}
166		for _, tt := range tests {
167			t.Run(tt.name, func(t *testing.T) {
168				s, fixtures := nexusFake(t)
169				base := s.URL(benchHTTPPort)
170				withImageSearcher(t, nexusOnlySearcher(t))
171	
172				m := runLot(t, nexusMembersModel(t, base, "docker-hosted", "docker-proxy"), tt.query, 2)
173	
174				wantOnlyMemberCatalogsAsked(t, s, fixtures)
175				var want []string
176				for _, r := range tt.hosted {
177					want = append(want, memberKey("nx", base, "docker-hosted")+":"+r)
178				}
179				for _, r := range tt.proxy {
180					want = append(want, memberKey("nx", base, "docker-proxy")+":"+r)
181				}
182				if got := rowsOf(m); !slices.Equal(sorted(got), sorted(want)) {
183					t.Errorf("rows = %v, want %v", got, want)
184				}
185				for prefix, rows := range map[string][]string{"docker-hosted": tt.hosted, "docker-proxy": tt.proxy} {
186					wantV := imagesearch.VerdictOK
187					if len(rows) == 0 {
188						wantV = imagesearch.VerdictNoResult
189					}
190					wantVerdict(t, m, memberKey("nx", base, prefix), wantV)
191				}
192			})
193		}
194	}
