196	// The same members, once a lot has run, are listed as "Cached only" under their
197	// own labels, and nothing is Failed or Refused.
198	func TestNexusMembersByPathAreCachedOnlyAndHealthy(t *testing.T) {
199		s, _ := nexusFake(t)
200		base := s.URL(benchHTTPPort)
201		withImageSearcher(t, nexusOnlySearcher(t))
