203		m := runLot(t, nexusMembersModel(t, base, "docker-hosted", "docker-proxy"), "base", 2)
204	
205		_, vals := headerLines(m)
206		if want := "nx/docker-hosted, nx/docker-proxy"; vals["Cached only"] != want {
207			t.Errorf("Cached only = %q, want %q", vals["Cached only"], want)
