216	// Q2 (i): an entry that declares `parent: nx` is a member too, and is read under
217	// its prefix exactly like a discovered one. The group itself is left unchecked:
218	// with no discovered members it is offered as an entry of its own, and this test
219	// is about the members.
220	func TestDeclaredNexusMembersWalkTheirOwnCatalog(t *testing.T) {
221		s, fixtures := nexusFake(t)
222		base := s.URL(benchHTTPPort)
223		withImageSearcher(t, nexusOnlySearcher(t))
224	
225		m := modelWithGroups(t, []config.RegistryItem{
226			anonymousNexusGroup(base),
227			declaredMember(base, "hosted", "docker-hosted"),
228			declaredMember(base, "proxy", "docker-proxy"),
229		}, nil)
230		m.registryBrowser.selectedRegs["nx"] = false
231		m = runLot(t, m, "base", 2)
232	
233		wantOnlyMemberCatalogsAsked(t, s, fixtures)
234		want := []string{"hosted:docker-hosted/shared/base", "proxy:docker-proxy/shared/base"}
235		if got := rowsOf(m); !slices.Equal(sorted(got), want) {
236			t.Errorf("rows = %v, want %v", got, want)
237		}
238		wantVerdict(t, m, "hosted", imagesearch.VerdictOK)
239		wantVerdict(t, m, "proxy", imagesearch.VerdictOK)
240	}
