362	// A prefix that is not a repository path cannot name a catalog: the member is
363	// refused with a cause that names the prefix, no request is sent for it, and the
364	// other member is searched as usual.
365	func TestAMemberWithAnInvalidPrefixIsRefusedWithoutARequest(t *testing.T) {
366		for _, bad := range []string{"Docker-Hosted", "a//b", "../x"} {
367			t.Run(bad, func(t *testing.T) {
368				srv := newPathServer(t, map[string]int{"/v2/b/_catalog": http.StatusOK})
369				withImageSearcher(t, wiredLikeProduction(srv.Server))
370				logs := captureLog(t)
371	
372				groups := map[string]cache.RegistryGroupEntry{"nx": {Members: []cache.RegistryGroupMember{
373					{Alias: "bad", URL: srv.URL, RepoPrefix: bad},
374					{Alias: "b", URL: srv.URL, RepoPrefix: "b"},
375				}}}
376				m := modelWithGroups(t, []config.RegistryItem{anonymousNexusGroup(srv.URL)}, groups)
377				m = runLot(t, m, "nginx", 2)
378	
379				wantVerdict(t, m, memberKey("nx", srv.URL, bad), imagesearch.VerdictRefused)
380				wantVerdict(t, m, memberKey("nx", srv.URL, "b"), imagesearch.VerdictOK)
381				if n := srv.total(); n != 1 {
382					t.Errorf("the server got %d requests, want 1 (b's catalog only)", n)
383				}
384				out := logs.String()
385				line := "INFO [oci_resources] image search on nx/bad: unsupported or refused:"
386				if !strings.Contains(out, line) || !strings.Contains(out, bad) {
387					t.Errorf("journal = %q, want %q naming the prefix %q", out, line, bad)
388				}
389				if strings.Contains(out, "ERROR") {
390					t.Errorf("a refusal was logged as an error: %q", out)
391				}
392				_, vals := headerLines(m)
393				if !strings.Contains(vals["Refused"], "nx/bad") {
394					t.Errorf("Refused = %q, want it to list nx/bad", vals["Refused"])
395				}
396			})
397		}
398	}
