400	// What the browser hands the Searcher for each kind of entry: the flag is set
401	// for the members of a Nexus group (discovered, and declared with `parent:`)
402	// that have a prefix, and for nothing else. The same predicate as listsCacheOnly.
403	func TestBuildEntriesFlagsTheCatalogUnderThePrefix(t *testing.T) {
404		member := func(alias, prefix string) cache.RegistryGroupMember {
405			return cache.RegistryGroupMember{Alias: alias, URL: "nx.example.com", RepoPrefix: prefix}
406		}
407		harbor := config.RegistryItem{Slug: "hb", Kind: config.KindGroup, Provider: config.ProviderHarbor, URL: "harbor.example.com", Alias: "hb"}
408		generic := config.RegistryItem{Slug: "gn", Kind: config.KindGroup, Provider: config.ProviderGeneric, URL: "reg.example.com", Alias: "gn"}
409		nexusPlain := config.RegistryItem{Slug: "n2", Kind: config.KindRegistry, Provider: config.ProviderNexus, URL: "n2.example.com", Alias: "n2", RepoPrefix: "p"}
410		solo := config.RegistryItem{Slug: "solo", Kind: config.KindRegistry, URL: "solo.example.com", Alias: "solo", RepoPrefix: "p"}
411		hub := config.RegistryItem{Slug: "hub", Kind: config.KindRegistry, URL: "docker.io", Alias: "hub"}
412		declared := declaredMember("decl.example.com", "decl", "docker-hosted")
413		declaredGeneric := config.RegistryItem{Slug: "declg", Kind: config.KindRegistry, Parent: "gn", URL: "declg.example.com", Alias: "declg", RepoPrefix: "p"}
414		declaredHarbor := config.RegistryItem{Slug: "declh", Kind: config.KindRegistry, Parent: "hb", URL: "declh.example.com", Alias: "declh", RepoPrefix: "p"}
415		declaredOrphan := config.RegistryItem{Slug: "declo", Kind: config.KindRegistry, Parent: "zz", URL: "declo.example.com", Alias: "declo", RepoPrefix: "p"}
416		regs := []config.RegistryItem{
417			nexusGroup(), harbor, generic, nexusPlain, solo, hub,
418			declared, declaredGeneric, declaredHarbor, declaredOrphan,
419		}
420	
421		tests := []struct {
422			name   string
423			groups map[string]cache.RegistryGroupEntry
424			want   map[string]bool // Alias -> CatalogUnderPrefix
425		}{
426			{
427				name:   "nothing discovered",
428				groups: nil,
429				want: map[string]bool{
430					"nx": false, // the group itself has no prefix of its own
431					"hb": false, "gn": false, "n2": false, "solo": false, "hub": false,
432					"decl": true, "declg": false, "declh": false, "declo": false,
433				},
434			},
435			{
436				name: "members discovered",
437				groups: map[string]cache.RegistryGroupEntry{
438					"nx": {Members: []cache.RegistryGroupMember{member("nx-a", "docker-hosted"), member("nx-b", "docker-proxy")}},
439					"hb": {Members: []cache.RegistryGroupMember{member("hb-a", "library")}},
440					"gn": {Members: []cache.RegistryGroupMember{member("gn-a", "team")}},
441				},
442				want: map[string]bool{
443					"nx-a": true, "nx-b": true, "hb-a": false, "gn-a": false,
444					"n2": false, "solo": false, "hub": false,
445					"decl": true, "declg": false, "declh": false, "declo": false,
446				},
447			},
448		}
449		for _, tt := range tests {
450			t.Run(tt.name, func(t *testing.T) {
451				b := newRegistryBrowser(regs, tt.groups, nil, 120, 40)
452				got := map[string]bool{}
453				for _, e := range b.entries {
454					tg := b.targetFor(e)
455					got[e.Alias] = tg.CatalogUnderPrefix
456					if tg.RepoPrefix != e.repoPrefix {
457						t.Errorf("%s: Target.RepoPrefix = %q, want %q", e.Alias, tg.RepoPrefix, e.repoPrefix)
458					}
459				}
460				if len(got) != len(tt.want) {
461					t.Fatalf("entries = %v, want aliases %v", got, tt.want)
462				}
463				for alias, want := range tt.want {
464					if g, ok := got[alias]; !ok || g != want {
465						t.Errorf("%s: CatalogUnderPrefix = %v (present %v), want %v", alias, g, ok, want)
466					}
467				}
468			})
469		}
470	}
