472	// The flag reaches the Searcher through a real lot: startImageSearch builds each
473	// Target with targetFor, so what the Searcher sees is what the user would get.
474	func TestTheLotHandsTheSearcherTheCatalogUnderPrefixFlag(t *testing.T) {
475		var mu sync.Mutex
476		seen := map[string]imagesearch.Target{}
477		withImageSearcher(t, imagesearch.SearcherFunc(func(_ context.Context, tg imagesearch.Target, _ imagesearch.Query) ([]imagesearch.Image, bool, error) {
478			mu.Lock()
479			seen[tg.EntryKey] = tg
480			mu.Unlock()
481			return nil, false, nil
482		}))
483	
484		const base = "http://nexus.invalid"
485		items := []config.RegistryItem{
486			anonymousNexusGroup(base),
487			declaredMember(base, "decl", "docker-proxy"),
488			genericEntry(base, "solo", "docker-hosted"),
489		}
490		m := modelWithGroups(t, items, discoveredMembers(base, "docker-hosted"))
491		runLot(t, m, "nginx", 3)
492	
493		for key, want := range map[string]bool{
494			memberKey("nx", base, "docker-hosted"): true,  // discovered member
495			"decl":                                 true,  // declared member
496			"solo":                                 false, // standalone, same host
497		} {
498			mu.Lock()
499			tg, ok := seen[key]
500			mu.Unlock()
501			if !ok {
502				t.Errorf("the Searcher never saw %s", key)
503				continue
504			}
505			if tg.CatalogUnderPrefix != want {
506				t.Errorf("%s: Target.CatalogUnderPrefix = %v, want %v", key, tg.CatalogUnderPrefix, want)
507			}
508		}
509	}
