63	// prefix (hosted/nginx, proxy/nginx-x, group/nginx-y), the way a generic
64	// registry that fronts several repositories does.
65	func catalogRequests(t *testing.T, status int) (*httptest.Server, *atomic.Int32) {
66		t.Helper()
67		var n atomic.Int32
68		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
69			if r.URL.Path != "/v2/_catalog" {
70				http.NotFound(w, r)
71				return
72			}
