77			}
78			w.Header().Set("Content-Type", "application/json")
79			_, _ = w.Write([]byte(`{"repositories":["hosted/nginx","proxy/nginx-x","group/nginx-y","other/nginx"]}`))
80		}))
81		t.Cleanup(srv.Close)
82		return srv, &n
83	}
