213	// A walk still in flight when a new lot replaces its lot gives the new lot no
214	// late result: the generation drops the old answer.
215	func TestALateWalkOfAReplacedLotGivesTheNewLotNothing(t *testing.T) {
216		release := make(chan struct{})
217		entered := make(chan struct{}, 8)
218		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
219			entered <- struct{}{}
220			select {
221			case <-release:
222			case <-r.Context().Done():
223			}
224			_, _ = w.Write([]byte(`{"repositories":["hosted/nginx"]}`))
225		}))
226		t.Cleanup(srv.Close)
227		t.Cleanup(func() { close(release) })
228		withImageSearcher(t, wiredLikeProduction(srv))
229	
230		m, cmd := submitRaw(t, sharedHostModel(t, srv.URL), "nginx")
231		old := runCmds(t, cmd)
232		<-entered
233		oldGen := m.registryBrowser.gen
234	
235		// The new lot replaces the old one (and cancels its context).
236		b := m.registryBrowser
237		b.startImageSearch("nginx", nil)
238		if b.gen == oldGen {
239			t.Fatal("the new lot kept the old generation")
240		}
241		late := recvResult(t, old)
242		m = feed(t, m, late)
243		if rows := rowsOf(m); len(rows) != 0 {
244			t.Errorf("rows = %v, want none from the replaced lot", rows)
245		}
246		if got := m.RegistryBrowserOutcomes(); len(got) != 0 {
247			t.Errorf("outcomes = %v, want none from the replaced lot", got)
248		}
249	}
