333	// buildEntries expands every configured registry into the lines the picker
334	// shows: a group into its cached members under a header, anything else into
335	// itself.
336	//
337	// A selection is remembered as the entries that were *un*checked, so a member
338	// discovered since the last visit arrives checked like every other new one.
339	func (b *RegistryBrowser) buildEntries(groups map[string]cache.RegistryGroupEntry, deselected map[string]bool) {
340		b.entries = nil
341		b.rows = nil
342		bySlug := make(map[string]config.RegistryItem, len(b.registries))
343		for _, reg := range b.registries {
344			bySlug[reg.Slug] = reg
345		}
346		for _, reg := range b.registries {
347			alias := browserAlias(reg)
348			// Members share their group's host and therefore its single credential
349			// entry, so they share the decision the group made about using it.
