361					repoPrefix: reg.RepoPrefix,
362					key:        reg.Slug,
363					cachedOnly: cacheOnly,
364					// The same predicate, narrowed to the entries that have a prefix.
365					catalogUnderPrefix: cacheOnly && reg.RepoPrefix != "",
366				})
367				continue
368			}
