370			b.rows = append(b.rows, pickerRow{groupSlug: reg.Slug, label: alias, entry: -1})
371			for _, m := range members {
372				b.rows = append(b.rows, pickerRow{label: "  " + m.Alias, entry: len(b.entries)})
373				b.entries = append(b.entries, browserRegistryEntry{
374					URL:         m.URL,
