12	// filterStops returns the values `r` cycles through for the tags tab.
13	func (b *RegistryBrowser) filterStops() []resultFilter {
14		keys := make([]string, len(b.tags))
15		for i, t := range b.tags {
16			keys[i] = t.EntryKey
17		}
18		return b.filterStopsFor(keys)
19	}
20	
21	// filterStopsFor returns the values `r` cycles through for results coming from
22	// the given entry keys, in order of first appearance: every group that
23	// produced results, then every individual registry, then off. The group level
24	// is what makes "everything from this Nexus" one keystroke rather than eight.
25	// Repeated keys collapse.
26	func (b *RegistryBrowser) filterStopsFor(keys []string) []resultFilter {
27		seenGroup, seenEntry := map[string]bool{}, map[string]bool{}
28		var groups, singles []resultFilter
29		for _, key := range keys {
30			entry := b.entryFor(key)
31			if entry != nil && entry.ParentSlug != "" && !seenGroup[entry.ParentSlug] {
32				seenGroup[entry.ParentSlug] = true
33				groups = append(groups, resultFilter{groupSlug: entry.ParentSlug})
34			}
35			if !seenEntry[key] {
36				seenEntry[key] = true
37				singles = append(singles, resultFilter{entryKey: key})
38			}
39		}
40		// A single source has nothing to filter down to.
41		if len(singles) <= 1 {
42			return nil
43		}
44		// A group holding every result and every member says the same as "off".
45		if len(groups) == 1 {
46			n := countMembers(b.entries, groups[0].groupSlug)
47			inGroup := 0
48			for _, f := range singles {
49				if e := b.entryFor(f.entryKey); e != nil && e.ParentSlug == groups[0].groupSlug {
50					inGroup++
51				}
52			}
53			if inGroup == len(singles) && len(singles) == n {
54				groups = nil
55			}
56		}
57		return append(groups, singles...)
58	}
59	
60	// countMembers returns how many entries belong to a group.
61	func countMembers(entries []browserRegistryEntry, slug string) int {
62		n := 0
63		for _, e := range entries {
64			if e.ParentSlug == slug {
65				n++
66			}
67		}
68		return n
69	}
