76	// nextFilter returns the stop after cur: off goes to the first stop, the last
77	// stop and any unknown filter go back to off.
78	func nextFilter(stops []resultFilter, cur resultFilter) resultFilter {
79		if len(stops) == 0 {
80			return resultFilter{}
81		}
82		if cur.isEmpty() {
83			return stops[0]
84		}
85		for i, s := range stops {
86			if s == cur {
87				if i+1 < len(stops) {
88					return stops[i+1]
89				}
90				return resultFilter{}
91			}
92		}
93		return resultFilter{}
94	}
